package com.fintrack.controller; import com.fintrack.model.User; import com.fintrack.repository.UserRepository; import com.fintrack.service.CurrentUser; import org.springframework.security.core.Authentication; import org.springframework.web.bind.annotation.*;
@RestController @RequestMapping("/api/profile") public class ProfileController{private final CurrentUser current;private final UserRepository repo;public ProfileController(CurrentUser c,UserRepository r){current=c;repo=r;}@GetMapping public User get(Authentication a){return current.get(a);}@PutMapping public User update(@RequestBody User x,Authentication a){User u=current.get(a);if(x.getName()!=null&&!x.getName().isBlank())u.setName(x.getName());if(x.getPhone()!=null)u.setPhone(x.getPhone());return repo.save(u);}}
